create extension if not exists pgcrypto;
create table public.user_privacy_settings (user_id uuid primary key references auth.users(id) on delete cascade, profile_visibility text not null default 'public' check (profile_visibility in ('public','connections','private')), discoverability_enabled boolean not null default true, contact_import_enabled boolean not null default false, messaging_policy text not null default 'requests' check (messaging_policy in ('connections','requests','nobody')), translation_enabled boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.consent_records (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, purpose text not null, status text not null check (status in ('granted','denied','revoked')), source text not null default 'pantavion', granted_at timestamptz, revoked_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check ((status='granted' and granted_at is not null and revoked_at is null) or (status='revoked' and revoked_at is not null) or status='denied'));
create index consent_records_user_purpose_idx on public.consent_records(user_id,purpose,created_at desc);
create table public.contact_sources (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, source_type text not null check(source_type in ('device','google','microsoft','apple','csv','vcard','manual','other')), external_account_hint text, consent_record_id uuid references public.consent_records(id) on delete set null, status text not null default 'active' check(status in ('active','paused','revoked','error')), last_synced_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.contacts (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, source_id uuid references public.contact_sources(id) on delete set null, linked_user_id uuid references auth.users(id) on delete set null, display_name text,email text,phone text,source_external_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(linked_user_id is not null or nullif(btrim(coalesce(email,'')),'') is not null or nullif(btrim(coalesce(phone,'')),'') is not null or nullif(btrim(coalesce(display_name,'')),'') is not null));
create table public.relationships (id uuid primary key default gen_random_uuid(), requester_id uuid not null references auth.users(id) on delete cascade, addressee_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','declined','removed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(requester_id<>addressee_id));
create unique index relationships_pair_unique_idx on public.relationships(least(requester_id,addressee_id),greatest(requester_id,addressee_id));
create table public.user_blocks(blocker_id uuid not null references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,reason text,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),kind text not null default 'direct' check(kind in ('direct','group','channel','elite_private')),title text,created_by uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.conversation_members(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('owner','admin','member')),joined_at timestamptz not null default now(),left_at timestamptz,primary key(conversation_id,user_id),check(left_at is null or left_at>=joined_at));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,client_message_id text,body text,original_language text,message_type text not null default 'text' check(message_type in ('text','image','video','audio','file','system')),reply_to_message_id uuid references public.messages(id) on delete set null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),edited_at timestamptz,deleted_at timestamptz,check(message_type<>'text' or nullif(btrim(coalesce(body,'')),'') is not null));
create table public.message_receipts(message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,state text not null check(state in ('queued','accepted','delivered','read','failed')),occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb,primary key(message_id,user_id,state));
create or replace function public.pantavion_is_conversation_member(p_conversation_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.conversation_members where conversation_id=p_conversation_id and user_id=p_user_id and left_at is null)$$;
create or replace function public.pantavion_has_block_between(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.user_blocks where (blocker_id=a and blocked_id=b) or (blocker_id=b and blocked_id=a))$$;
revoke all on function public.pantavion_is_conversation_member(uuid,uuid) from public; grant execute on function public.pantavion_is_conversation_member(uuid,uuid) to authenticated;
revoke all on function public.pantavion_has_block_between(uuid,uuid) from public; grant execute on function public.pantavion_has_block_between(uuid,uuid) to authenticated;
alter table public.user_privacy_settings enable row level security; alter table public.consent_records enable row level security; alter table public.contact_sources enable row level security; alter table public.contacts enable row level security; alter table public.relationships enable row level security; alter table public.user_blocks enable row level security; alter table public.conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.messages enable row level security; alter table public.message_receipts enable row level security;
create policy privacy_owner on public.user_privacy_settings for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy consent_owner on public.consent_records for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy contact_sources_owner on public.contact_sources for all to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy contacts_owner on public.contacts for all to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy relationships_read on public.relationships for select to authenticated using(auth.uid() in(requester_id,addressee_id));
create policy relationships_insert on public.relationships for insert to authenticated with check(auth.uid()=requester_id and requester_id<>addressee_id and not public.pantavion_has_block_between(requester_id,addressee_id));
create policy blocks_owner on public.user_blocks for all to authenticated using(auth.uid()=blocker_id) with check(auth.uid()=blocker_id);
create policy conversations_read on public.conversations for select to authenticated using(public.pantavion_is_conversation_member(id,auth.uid()));
create policy conversations_insert on public.conversations for insert to authenticated with check(auth.uid()=created_by);
create policy members_read on public.conversation_members for select to authenticated using(public.pantavion_is_conversation_member(conversation_id,auth.uid()));
create policy messages_read on public.messages for select to authenticated using(public.pantavion_is_conversation_member(conversation_id,auth.uid()));
create policy messages_insert on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.pantavion_is_conversation_member(conversation_id,auth.uid()));
grant select,insert,update,delete on public.user_privacy_settings,public.consent_records,public.contact_sources,public.contacts,public.relationships,public.user_blocks,public.conversations,public.conversation_members,public.messages,public.message_receipts to authenticated;
drop policy if exists "profiles self read" on public.profiles;
create policy profiles_privacy_read on public.profiles for select to authenticated using(auth.uid()=id or exists(select 1 from public.user_privacy_settings ps where ps.user_id=id and ps.profile_visibility='public' and ps.discoverability_enabled));
insert into public.user_privacy_settings(user_id) select id from auth.users on conflict(user_id) do nothing;